      '<rect onload="alert(1)"/>',
      '<foreignObject><iframe src="x"/></foreignObject>',
      '<a href="javascript:alert(1)"><rect/></a>',
      '<image href="https://tracker.example/p.png"/>',
      '<use xlink:href="https://evil.example/s.svg#x"/>',
      '<set attributeName="href" to="javascript:alert(1)"/>',
