/**
 * Cookie handling. Session cookies are Secure, HttpOnly, SameSite=Lax and
 * Path=/ (spec AUTH-04); the CSRF companion is readable by the SPA so it can
 * echo the token in a request header.
 */

export const USER_SESSION_COOKIE = 'yj_s'
export const ADMIN_SESSION_COOKIE = 'yj_a'
export const USER_CSRF_COOKIE = 'yj_csrf'
export const ADMIN_CSRF_COOKIE = 'yj_acsrf'
export const CSRF_HEADER = 'x-yeopjari-csrf'

/**
 * Names which session the caller means when both cookies are present. The
 * member app and the admin console can be signed in at once, possibly as
 * different accounts, so "who am I" is ambiguous without it.
 */
export const SESSION_HINT_HEADER = 'x-yeopjari-session'

export type SessionKind = 'user' | 'admin'

export function sessionCookieName(kind: SessionKind): string {
  return kind === 'admin' ? ADMIN_SESSION_COOKIE : USER_SESSION_COOKIE
}

export function csrfCookieName(kind: SessionKind): string {
  return kind === 'admin' ? ADMIN_CSRF_COOKIE : USER_CSRF_COOKIE
}

export function readCookies(request: Request): Record<string, string> {
  const header = request.headers.get('cookie')
  if (!header) return {}
  const out: Record<string, string> = {}
  for (const part of header.split(';')) {
    const eq = part.indexOf('=')
    if (eq <= 0) continue
    const name = part.slice(0, eq).trim()
    const value = part.slice(eq + 1).trim()
    if (name) out[name] = decodeURIComponent(value)
  }
  return out
}

export interface CookieOptions {
  maxAgeSeconds?: number
  httpOnly?: boolean
  secure: boolean
  sameSite?: 'Lax' | 'Strict' | 'None'
  path?: string
}

export function serializeCookie(name: string, value: string, options: CookieOptions): string {
  const parts = [`${name}=${encodeURIComponent(value)}`, `Path=${options.path ?? '/'}`]
  parts.push(`SameSite=${options.sameSite ?? 'Lax'}`)
  if (options.httpOnly !== false) parts.push('HttpOnly')
  if (options.secure) parts.push('Secure')
  if (options.maxAgeSeconds !== undefined) {
    parts.push(`Max-Age=${Math.max(0, Math.floor(options.maxAgeSeconds))}`)
    const expires = new Date(Date.now() + Math.max(0, options.maxAgeSeconds) * 1000)
    parts.push(`Expires=${expires.toUTCString()}`)
  }
  return parts.join('; ')
}

export function clearCookie(name: string, secure: boolean): string {
  return serializeCookie(name, '', { secure, maxAgeSeconds: 0 })
}
/**
 * IndexNow: telling search engines a page is new instead of waiting for them
 * to find it. One POST to the shared endpoint reaches every participant -
 * Bing, 네이버 (since 2023-07), Yandex, Seznam. Google does not take part; it
 * reads the sitemap.
 *
 * The key is derived, not stored: an HMAC of a fixed label under the token
 * key, the same on every instance, served at /<key>.txt as the protocol asks.
 * It proves only that the pinger controls the site, so it need not be secret.
 */
import type { Env } from '../env.js'
import { hmacHex } from '../util/crypto.js'

export async function indexNowKey(env: Env): Promise<string> {
  return (await hmacHex(env.keys.tokenSign, 'indexnow-key')).slice(0, 32)
}

/** Pings for these paths; never throws (a failed ping only means slower discovery). */
export async function pingIndexNow(env: Env, paths: string[]): Promise<boolean> {
  return (await pingIndexNowStatus(env, paths)) === 'sent'
}

/**
 * The same, saying what happened: 'sent', 'skipped' (development, offline,
 * nothing to send) or the gateway's status code. A worker's fetch carries no
 * User-Agent unless given one, and the shared endpoint refused the first
 * calls made from Cloudflare that way while the same call from a laptop was
 * accepted - so one is set, as for OpenDART.
 */
export async function pingIndexNowStatus(env: Env, paths: string[]): Promise<string> {
  const origin = new URL(env.publicUrl)
  if (env.dev || env.offline || origin.protocol !== 'https:' || paths.length === 0) return 'skipped'
  const key = await indexNowKey(env)
  try {
    const response = await fetch('https://api.indexnow.org/indexnow', {
      method: 'POST',
      headers: { 'content-type': 'application/json; charset=utf-8', 'user-agent': 'yeopjari/1.0 (+https://yeopjari.bid)' },
      body: JSON.stringify({
        host: origin.host,
        key,
        keyLocation: `${origin.origin}/${key}.txt`,
        urlList: [...new Set(paths)].slice(0, 1000).map((path) => `${origin.origin}${path}`),
      }),
    })
    return response.ok ? 'sent' : `http ${response.status}`
  } catch (err) {
    return `error ${String(err instanceof Error ? err.message : err).slice(0, 80)}`
  }
}
