import { Router } from '../http/router.js'
import { json } from '../http/respond.js'
import { elevate } from '../db.js'
import { parse, v } from '../util/validate.js'
import { consume, globalSubject, ipSubject } from '../quota.js'
import { normalisePath, redactSecrets } from '../http/pipeline.js'

export function clientErrorRoutes(): Router {
  const router = new Router()
  router.post(
    '/api/v1/client-errors',
    async (ctx) => {
      const input = parse(
        {
          path: v.string({ min: 1, max: 300, label: '경로' }),
          message: v.string({ min: 1, max: 500, label: '내용' }),
        },
        await ctx.body(),
      )
      await consume(ctx.sql, ipSubject(ctx.ipHash), [{ action: 'client.error', window: 'day', max: 20 }])
      await consume(ctx.sql, globalSubject('client_errors'), [{ action: 'client.error', window: 'day', max: 500 }])
