        SELECT priv.record_error_alert(${`CLIENT ${path} client`}, 'CLIENT', ${path}, 'client', ${message}, ${ctx.requestId}, 1440)`)
      return json({ ok: true }, { status: 202 })
    },
    { auth: 'public', skipCsrf: true, systemPhase: true, summary: '화면 오류 보고' },
  )
  return router
