/**
 * Outbound mail.
 *
 * Three drivers cover the deployments we ship: `resend` for the hosted launch,
 * `smtp` for a self-hosted or offline relay, and `console` which records the
 * message without sending - the default for development and for an isolated
 * network where no relay exists.
 */
import type { Env } from '../env.js'
import { upstreamUnavailable } from '../errors.js'
import type { MailMessage } from './templates.js'

/**
 * The account-wide mail gateway (the mail-gateway Worker), when this runs on
 * Cloudflare with its service binding. It takes Resend's request unchanged,
 * sends through Resend while the shared free quota (100 a day, 3,000 a month,
 * received mail included) has room and through Cloudflare Email Service past
 * it. Node and local runs have no binding and talk to Resend directly.
 */
export interface MailGateway {
  fetch(input: string, init?: RequestInit): Promise<Response>
}

let gateway: MailGateway | undefined

/** Called by the Pages Function with its MAIL binding; the binding is the same for the isolate's life. */
export function useMailGateway(binding: MailGateway | undefined): void {
  gateway = binding
}

async function postToResend(init: RequestInit): Promise<Response> {
  if (gateway) {
    try {
      return await gateway.fetch('https://mail-gateway/emails', init)
    } catch {
      // The gateway itself unreachable: Resend directly, as before it existed.
    }
  }
  return fetch('https://api.resend.com/emails', init)
}

export interface SendResult {
  ok: boolean
  /** Provider message id when one is returned. */
  id: string
  /** Classification for the job's retry decision, not shown to members. */
  errorClass: 'none' | 'transient' | 'permanent' | 'disabled'
  detail: string
  }

  private async sendResend(message: MailMessage): Promise<SendResult> {
    const apiKey = this.env.mail.resendApiKey
    if (!apiKey) {
      return { ok: false, id: '', errorClass: 'permanent', detail: 'RESEND_API_KEY가 설정되지 않았습니다.' }
    }
    const from = this.env.mail.from.includes('<')
      ? this.env.mail.from
      : `${this.options.fromName} <${this.env.mail.from}>`

    try {
      const response = await postToResend({
        method: 'POST',
        headers: {
          authorization: `Bearer ${apiKey}`,
          'content-type': 'application/json',
          'x-mail-project': 'yeopjari',
          // Lets the provider collapse a retry of the same message (JOB-04).
          'idempotency-key': await idempotencyKeyFor(message),
        },
        body: JSON.stringify({
          from,
          to: [message.to],
          subject: message.subject,
          text: message.text,
          ...(this.env.mail.replyTo ? { reply_to: this.env.mail.replyTo } : {}),
        }),
      })

      if (response.ok) {
        const body = (await response.json().catch(() => ({}))) as { id?: string }
        return { ok: true, id: body.id ?? '', errorClass: 'none', detail: '' }
      }
      const text = (await response.text().catch(() => '')).slice(0, 300)
      const transient = response.status === 429 || response.status >= 500
      return {
        ok: false,
        id: '',
        errorClass: transient ? 'transient' : 'permanent',
        detail: `resend ${response.status}: ${text}`,
      }
    } catch (err) {
      return { ok: false, id: '', errorClass: 'transient', detail: `resend 연결 실패: ${String(err).slice(0, 200)}` }
    }
  }

  /**
   * Minimal SMTP submission over an existing relay. Node-only: the socket API
 * A page with nothing on it but a name and an address. Kept out of search
 * (noindex, follow) and the sitemap until something lands on it - a filing,
 * a review, the company's own introduction - so the site is judged by its
 * pages with substance; the page itself still works for anyone with the link.
 */
export function isThin(company: PublicCompany): boolean {
  return (
    company.disclosed_year === null &&
    !(company.disclosed_financials && company.disclosed_financials.length > 0) &&
    !company.summary &&
    !company.official_intro &&
    company.review_count === 0 &&
    company.salary_count === 0 &&
    !company.recent_filings &&
    !company.nps?.members
  )
}

/** The same rule in SQL, for the sitemap (o = app.organizations). */
export const SUBSTANTIAL_SQL = `(o.disclosed_year IS NOT NULL OR o.disclosed_financials IS NOT NULL OR o.summary <> ''
  OR o.official_intro <> '' OR o.review_count > 0 OR o.salary_count > 0
  OR EXISTS (SELECT 1 FROM app.disclosures d WHERE d.org_id = o.id)
  OR EXISTS (SELECT 1 FROM app.workplaces w WHERE w.org_id = o.id AND w.active))`

